/**
 * Test the XML-RPC subset which carries the JSON-able values in isolation.
 */

// This code has been automatically generated by aas-core-codegen.
// Do NOT edit or append.

import * as AasCommon from "../src/common";
import * as AasTypes from "../src/types";
import * as AasXmlCommon from "../src/xmlcommon";
import * as AasXmlRpc from "../src/xmlrpc";

const NAMESPACE = "https://dummy.com";

/**
 * Tokenize `text` and consume the opening tag of its root element.
 *
 * @remarks
 *
 * The module under test expects a cursor which already stands *inside* the
 * element whose content it is to read, exactly as the de/serialization of
 * the model hands it over.
 */
function enter(text: string): AasXmlCommon.XmlCursor {
  const tokensOrError = AasXmlCommon.tokenizeXml(text);
  if (tokensOrError.error !== null) {
    throw new Error(
      `Expected a well-formed XML, but got: ${tokensOrError.error.message}`
    );
  }

  const cursor = new AasXmlCommon.XmlCursor(tokensOrError.mustValue());

  const rootOrError = AasXmlCommon.readRequiredRootOpenTag(cursor);
  if (rootOrError.error !== null) {
    throw new Error(
      `Expected a root element, but got: ${rootOrError.error.message}`
    );
  }

  return cursor;
}

/**
 * Assert that `parsed` failed and give out its error.
 */
function mustError(
  parsed: AasCommon.Either<unknown, AasXmlCommon.DeserializationError>
): AasXmlCommon.DeserializationError {
  const error = parsed.error;
  if (error === null) {
    throw new Error("Expected an error, but the parsing succeeded");
  }
  return error;
}

test("a value round-trips through every discriminator", () => {
  const cursor = enter(
    `<v xmlns="${NAMESPACE}"><struct xmlns="">` +
      "<member><name>b</name><value><boolean>1</boolean></value></member>" +
      "<member><name>f</name><value><double>1.5</double></value></member>" +
      "<member><name>s</name><value><string>x</string></value></member>" +
      "<member><name>a</name><value><array><data>" +
        "<value><double>0</double></value>" +
      "</data></array></value></member>" +
      "</struct></v>"
  );

  const parsed = AasXmlRpc.parseValueContent(cursor);

  expect(parsed.error).toBeNull();
  expect(parsed.mustValue()).toStrictEqual({
    b: true,
    f: 1.5,
    s: "x",
    a: [0]
  });
});

test("the discriminator is a step of the path", () => {
  const cursor = enter(
    `<v xmlns="${NAMESPACE}"><boolean xmlns="">yes</boolean></v>`
  );

  const parsed = AasXmlRpc.parseValueContent(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual("boolean");
});

test("an element which is no discriminator gets no step", () => {
  // NOTE (mristin):
  // It is this very element which does not belong here, so naming it in
  // the path as well as in the message would say nothing more.
  const cursor = enter(`<v xmlns="${NAMESPACE}"><oops xmlns=""/></v>`);

  const parsed = AasXmlRpc.parseValueContent(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual("");
  expect(mustError(parsed).message).toContain("but got: 'oops'");
});

test("the path into a nested value", () => {
  const cursor = enter(
    `<v xmlns="${NAMESPACE}"><struct xmlns="">` +
      "<member><name>nested</name><value><array><data>" +
        "<value><double>0</double></value>" +
        "<value><string><oops/></string></value>" +
      "</data></array></value></member>" +
      "</struct></v>"
  );

  const parsed = AasXmlRpc.parseValueContent(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual(
    'struct/member[name="nested"]/value/array/data/*[1]/string'
  );
});

test("the array body is entered without its wrapper", () => {
  // NOTE (mristin):
  // A `JSONArray` property is represented by a `<data>` element directly,
  // with no `<array>` element around it, so the path has none either.
  const cursor = enter(
    `<v xmlns="${NAMESPACE}"><data xmlns="">` +
      "<value><boolean>yes</boolean></value>" +
      "</data></v>"
  );

  const parsed = AasXmlRpc.parseArrayBody(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual("data/*[0]/boolean");
});

test("the struct body is entered without its wrapper", () => {
  // NOTE (mristin):
  // A `JSONObject` property is represented by its `<member>` elements
  // directly, with no `<struct>` element around them.
  const cursor = enter(
    `<v xmlns="${NAMESPACE}">` +
      '<member xmlns=""><name>k</name><value><oops/></value></member>' +
      "</v>"
  );

  const parsed = AasXmlRpc.parseStructBody(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual(
    'member[name="k"]/value'
  );
});

test("the key of a member is escaped in the path", () => {
  const cursor = enter(
    `<v xmlns="${NAMESPACE}">` +
      '<member xmlns=""><name>a&amp;b/c&lt;d</name>' +
      "<value><oops/></value></member>" +
      "</v>"
  );

  const parsed = AasXmlRpc.parseStructBody(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual(
    'member[name="a&amp;b&#47;c&lt;d"]/value'
  );
});

test("a repeated member is refused", () => {
  const cursor = enter(
    `<v xmlns="${NAMESPACE}">` +
      '<member xmlns=""><name>k</name><value><double>1</double></value></member>' +
      '<member xmlns=""><name>k</name><value><double>2</double></value></member>' +
      "</v>"
  );

  const parsed = AasXmlRpc.parseStructBody(cursor);

  expect(parsed.error).not.toBeNull();
  expect(mustError(parsed).path.toString()).toStrictEqual('member[name="k"]');
  expect(mustError(parsed).message).toStrictEqual(
    "The member occurred more than once"
  );
});

test("neither an infinity nor a not-a-number is read", () => {
  for (const text of ["INF", "-INF", "NaN", "Infinity", "1e400"]) {
    const cursor = enter(
      `<v xmlns="${NAMESPACE}"><double xmlns="">${text}</double></v>`
    );

    const parsed = AasXmlRpc.parseValueContent(cursor);

    expect(parsed.error).not.toBeNull();
    expect(mustError(parsed).path.toString()).toStrictEqual("double");
  }
});

test("a value is written with its discriminator", () => {
  const cases: Array<[AasTypes.JsonValue, string]> = [
    [true, '<boolean xmlns="">1</boolean>'],
    [false, '<boolean xmlns="">0</boolean>'],
    [1, '<double xmlns="">1</double>'],
    [1.5, '<double xmlns="">1.5</double>'],
    ["a<b&c", '<string xmlns="">a&lt;b&amp;c</string>'],
    [
      [0],
      '<array xmlns=""><data><value><double>0</double></value></data></array>'
    ],
    [
      { k: 0 },
      '<struct xmlns=""><member><name>k</name>' +
        "<value><double>0</double></value></member></struct>"
    ]
  ];

  for (const [value, expected] of cases) {
    const parts = new Array<string>();
    AasXmlRpc.writeValueContent(parts, value);
    expect(parts.join("")).toStrictEqual(expected);
  }
});

test("the path of a failed write points into the value", () => {
  const parts = new Array<string>();

  expect(() =>
    AasXmlRpc.writeStructBody(parts, {
      "a b": [0, Number.POSITIVE_INFINITY]
    })
  ).toThrow(AasXmlCommon.SerializationError);

  try {
    AasXmlRpc.writeStructBody(new Array<string>(), {
      "a b": [0, Number.POSITIVE_INFINITY]
    });
  } catch (error) {
    expect(error).toBeInstanceOf(AasXmlCommon.SerializationError);
    expect((error as AasXmlCommon.SerializationError).path).toStrictEqual(
      '["a b"][1]'
    );
  }
});

